#!/usr/bin/env node
/*
 * Generates 20 separate SQL files (supabase/seed_tests_01.sql through
 * supabase/seed_tests_20.sql), one per test. Each file fits easily within the
 * Supabase SQL Editor's query size limit.
 *
 * Run once after applying supabase/schema.sql, by pasting each generated file's
 * contents into a new SQL Editor query. Re-run and re-paste any time
 * scripts/question-bank.js changes.
 *
 *   node scripts/export-supabase-seed-split.js
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { getSectionsForTest } = require('./lib/build-sections.js');

const TOTAL_TESTS = 20;
const DURATION_MINUTES = 150;
const OUT_DIR = path.join(__dirname, '..', 'supabase');

function sqlLiteral(value) {
  // Dollar-quoted string: safe even if the text contains single quotes
  // (several questions use possessives like "Piaget's theory").
  return `$jsonq$${value}$jsonq$`;
}

for (let testId = 1; testId <= TOTAL_TESTS; testId++) {
  const sections = getSectionsForTest(testId);
  const questionCount = sections.reduce((sum, s) => sum + s.questions.length, 0);
  const idPadded = String(testId).padStart(2, '0');
  const title = `TET Full Test ${idPadded}`;
  const questionsJson = JSON.stringify(sections);

  const lines = [];
  lines.push('-- Auto-generated by scripts/export-supabase-seed-split.js — do not edit by hand.');
  lines.push(`-- Test ${idPadded} of ${TOTAL_TESTS}.`);
  lines.push('-- Paste this into a new SQL Editor query and run it.');
  lines.push('');
  lines.push('insert into test_content (test_id, title, question_count, duration_minutes, questions)');
  lines.push('values');
  lines.push(
    `  ('test${idPadded}', ${sqlLiteral(title)}, ${questionCount}, ${DURATION_MINUTES}, ${sqlLiteral(questionsJson)}::jsonb)`
  );
  lines.push('on conflict (test_id) do update set');
  lines.push('  title = excluded.title,');
  lines.push('  question_count = excluded.question_count,');
  lines.push('  duration_minutes = excluded.duration_minutes,');
  lines.push('  questions = excluded.questions;');
  lines.push('');

  const outFile = path.join(OUT_DIR, `seed_tests_${idPadded}.sql`);
  fs.writeFileSync(outFile, lines.join('\n'));
  console.log(`Wrote ${outFile} (${questionCount} questions)`);
}

console.log(`\nAll 20 split SQL files generated in ${OUT_DIR}/.`);
console.log('Paste each one into a new SQL Editor query in Supabase and run.');
